func CSDiskSpaceStartRecovery(volumeURL unsafe.Pointer, bytesNeeded uint64, options int, outOperationUUID unsafe.Pointer, callbackQueue *foundation.NSObject, callback func(uint8, uint64, unsafe.Pointer)) {
	var __block_callback objc.Block
	if callback != nil {
		__block_callback = objc.NewBlock(func(_ objc.Block, blockParam0 uint8, blockParam1 uint64, blockParam2 unsafe.Pointer) {
			callback(blockParam0, blockParam1, blockParam2)
		})
		defer __block_callback.Release()
	}
	_fnCSDiskSpaceStartRecovery(volumeURL, bytesNeeded, options, outOperationUUID, callbackQueue.Ptr(), __block_callback)
}

